  ui_story_32230401_59_dialog_content = "Acabei de comprar estes por um bom dinheiro na Twin Pavilions Bay. Estas são as relíquias sagradas que a falecida Donzela do Dragão deixou para trás!",
  ui_story_32230401_60_dialog_content = "Relíquias sagradas...?!",
