  ui_story_32230401_64_dialog_content = "Quando o avô do atual imperador ainda ocupava o trono, ele uma vez salvou a Donzela Dragão de um polvo gigante durante uma viagem...",
  ui_story_32230401_65_dialog_content = "Hã?",
  ui_story_32230401_66_dialog_content = "A Donzela Dragão estava profundamente grata que ela deu a ele um pedaço de sua escama. Mas encontrou seu caminho para fora quando o palácio foi assaltado...",
  ui_story_32230401_67_dialog_content = "E eventualmente, veio até mim.",
