  ui_story_32230401_74_dialog_content = "Você está me dizendo para parar enquanto tenta me enganar, o principal especialista em Longzhou aqui?",
  ui_story_32230401_75_dialog_content = "Está vendo isso? Este é o autêntico sangue de dragão.",
  ui_story_32230401_76_dialog_content = "Não é apenas bronze simples?",
