  ui_story_32230401_78_dialog_content = "...!",
  ui_story_32230401_79_dialog_content = "Para criar a armadura mais resistente do mundo, eles oraram para a Donzela Dragão.",
  ui_story_32230401_80_dialog_content = "E para responder às suas preces, a Donzela do Dragão derramou um pouco de seu próprio sangue na forja.",
  ui_story_32230401_81_dialog_content = "Após milhares de anos, a tribo há muito se foi, mas esta última armadura inexpugnável no mundo...",
  ui_story_32230401_82_dialog_content = "É a única prova de que a Tribo Loom já existiu!",
  ui_story_32230401_83_dialog_content = "Impressionante, não é? Ninguém nunca viu um tesouro como este antes!",
  ui_story_32230401_84_dialog_content = "Concordo. Esta é a primeira vez até para mim.",
  ui_story_32230401_85_dialog_content = "Ei... Hahahahah!",
  ui_story_32230401_86_dialog_content = "Seus pirralhos insolentes! Como ousam zombar de mim enquanto tentam me enganar?",
  ui_story_32230401_87_dialog_content = "Cai fora, cai fora agora! E leve sua falsificação com você!",
  ui_story_32230401_88_dialog_content = "O comerciante vê a mancha de sangue quando alcança a balança. Ele para, franze a testa e a pega com um pano antes de jogá-la fora.",
  ui_story_32230401_89_dialog_content = "Cai fora!",
  ui_story_32230401_90_dialog_content = "Ding dong!",
  ui_story_32230401_91_dialog_content = "Hahaha!",
  ui_story_32230401_92_dialog_content = "Opa, desculpe, isso não é engraçado... Mas você realmente deu a ele!",
  ui_story_32230401_93_dialog_content = "Não quis constrangê-lo, já que sei o quanto as pessoas aqui sabem pouco sobre os dragões em Longzhou.",
  ui_story_32230401_94_dialog_content = "Até que ele mencionou a Tribo Loom...",
  ui_story_32230401_95_dialog_content = "Bem, por que não guardamos essa sua preciosa balança...",
