  ui_story_32230401_97_dialog_content = "O que há de errado? Ele pegou aleatoriamente entre aqueles brinquedos.",
  ui_story_32230401_98_dialog_content = "Era apenas algum tipo de embalagem, eu acho.",
  ui_story_32230401_99_dialog_content = "Sem rugas quando você esfrega, o artesanato único, o material resistente, mas suave...",
  ui_story_32230401_100_dialog_content = "Esta é uma relíquia da Tribo Loom.",
  ui_story_32230401_101_dialog_content = "A tribo antiga? Então o lojista não estava mentindo?",
  ui_story_32230401_102_dialog_content = "E que tal usar o seu sangue para fazer a armadura?",
  ui_story_32230401_103_dialog_content = "Isso é uma mentira.",
  ui_story_32230401_104_dialog_content = "Vi o quanto eles estavam imersos na tecelagem e me interessei, o suficiente para protegê-los de desastres por um tempo.",
  ui_story_32230401_105_dialog_content = "Durante aqueles dias pacíficos, eles rapidamente desenvolveram as melhores técnicas de tecelagem do mundo.",
  ui_story_32230401_106_dialog_content = "É assim que os mortais são: inteligentes e determinados. Tudo o que eles precisam é de uma chance.",
  ui_story_32230401_107_dialog_content = "Eu não sabia que isso realmente aconteceu...",
  ui_story_32230401_108_dialog_content = "A tribo inteira foi destruída em um incêndio e todas as suas técnicas foram perdidas.",
