  ui_story_32230401_114_dialog_content = "...",
  ui_story_32230401_115_dialog_content = "Não ultrapasse seus limites, mortal.",
  ui_story_32230401_116_dialog_content = "Uau, dragão... É um dragão! Urgh...!",
  ui_story_32230401_117_dialog_content = "...",
  ui_story_32230401_118_dialog_content = "(Então é assim que os dragões parecem quando estão com raiva! Aprendi algo novo hoje.)",
  ui_story_32230401_119_dialog_content = "...",
  ui_story_32230401_120_dialog_content = "Muito bem, hora da próxima loja!",
  ui_story_32230401_121_dialog_content = "O que estamos fazendo?",
  ui_story_32230401_122_dialog_content = "Venda minha balança para o modelo, claro!",
  ui_story_32230401_123_dialog_content = "Você ainda vai continuar com isso?",
  ui_story_32230601_1_dialog_content = "Artemísia! Cálamo! Eu também vendo gardênias—",
  ui_story_32230601_2_dialog_content = "Arroz de sorgo fresco à venda! Não se pode fazer zongzi sem ele!",
  ui_story_32230601_3_dialog_content = "Eu sei que hoje é o Festival das Cores de Longzhou, mas eu não esperava que fosse tão animado.",
  ui_story_32230601_4_dialog_content = "Deleitem seus olhos, todos! Minhas roupas vêm diretamente do oeste - uma visão rara de fato!",
  ui_story_32230601_5_dialog_content = "Eles até vendem roupas do Astra aqui.",
  ui_story_32230601_6_dialog_content = "Aha! Vejo que é um verdadeiro especialista! Venha dar uma olhada, amigo!",
  ui_story_32230601_7_dialog_content = "Essas roupas são de Astra, mas também têm muito do charme de Longzhou. Elas devem ter vindo de Twin Pavilions Bay.",
  ui_story_32230601_8_dialog_content = "É interessante vê-los todos deste lado do oceano.",
  ui_story_32230601_9_dialog_content = "Essas roupas foram cuidadosamente selecionadas pela Guilda Lin. Cada peça é completamente única.",
  ui_story_32230601_10_dialog_content = "Eles fazem os presentes perfeitos para as senhoras em sua vida.",
  ui_story_32230601_11_dialog_content = "E com o Festival das Cores logo ali na esquina, todos querem estar no seu melhor com roupas novinhas em folha!",
  ui_story_32230601_12_dialog_content = "Não podemos deixar as outras garotas ofuscarem as suas, certo?",
  ui_story_32230601_13_dialog_content = "Isso também é outra tradição do festival?",
  ui_story_32230601_14_dialog_content = "(Agora que penso nisso, Chen'ni sempre usa a mesma roupa. Eu me pergunto...)",
  ui_story_32230601_15_dialog_content = "Vejo que você está realmente pensando nisso. Como sinal da minha sinceridade, vou oferecer o menor preço da região...",
  ui_story_32230601_16_dialog_content = "<color=#e8d9bb>Momentos depois</color>",
  ui_story_32230601_17_dialog_content = "...",
  ui_story_32230601_18_dialog_content = "(Comprei antes mesmo de perceber! Os comerciantes do Reino Ji realmente são algo à parte...)",
  ui_story_32230601_19_dialog_content = "Ah bem, acho que já paguei por isso...",
  ui_story_32230601_20_dialog_content = "Pago por quê?",
  ui_story_32230601_21_dialog_content = "Ah! Chen'ni?",
  ui_story_32230601_22_dialog_content = "Hum, ouvi dizer que as meninas gostam de usar roupas novas durante o Festival das Cores. Você—",
  ui_story_32230601_23_dialog_content = "Sim, eu também!",
  ui_story_32230601_24_dialog_content = "Hã?",
  ui_story_32230601_25_dialog_content = "Não te disse antes? Minhas roupas também são uma manifestação dos meus poderes.",
  ui_story_32230601_26_dialog_content = "Eles são feitos de escamas de dragão, o que significa que são impermeáveis ao fogo, água e à influência de espíritos malignos. Claro, eu também posso mudar a aparência deles!",
  ui_story_32230601_27_dialog_content = "Que tipo de roupa eu deveria trocar, PlayerName? Talvez um dos vestidos da sua terra natal?",
  ui_story_32230601_28_dialog_content = "(Então não havia sentido em comprar isso afinal!)",
  ui_story_32230601_29_dialog_content = "Hahaha... Claro, isso parece bom.",
  ui_story_32230601_30_dialog_content = "?",
  ui_story_32230601_31_dialog_content = "Então... O que você comprou agora há pouco mesmo?",
  ui_story_32230601_32_dialog_content = "(Não posso fazer isso! Não posso dar isso a ela agora!)",
  ui_story_32230601_33_dialog_content = "N-Nada! Eu só fiquei surpreso em encontrar tantos produtos de Astra por aqui, só isso.",
  ui_story_32230601_34_dialog_content = "Olhe para lá!",
  ui_story_32230601_35_dialog_content = "Guloseimas e decorações ocidentais! Não perca a chance de comprá-las!",
  ui_story_32230601_36_dialog_content = "Esses parecem deliciosos! Vou pegar alguns!",
  ui_story_32230601_37_dialog_content = "(Ufa... Vou guardar isso por enquanto.)",
  ui_story_32230601_38_dialog_content = "A embalagem deste lanche parece tão apertada, e eu não consigo entender nada do que está escrito nela. Acho que é melhor experimentar primeiro!",
  ui_story_32230601_39_dialog_content = "Espere Chen'ni, isso é—",
  ui_story_32230601_40_dialog_content = "*mastiga*",
  ui_story_32230601_41_dialog_content = "Um biscoito militar super comprimido da Federação Illumina. Você deve adicionar água a ele...",
  ui_story_32230601_42_dialog_content = "*Golpe* Hum?",
  ui_story_32230601_43_dialog_content = "Th-O biscoito está se expandindo na minha boca!",
  ui_story_32230601_44_dialog_content = "Mantenha a calma, Chen'ni! Apenas desembucha!",
  ui_story_32230601_45_dialog_content = "Está tão seco! O biscoito está sugando toda a umidade do meu corpo!",
  ui_story_32230601_46_dialog_content = "Água... Preciso de água!",
  ui_story_32230601_47_dialog_content = "Há um rio ali!",
  ui_story_32230601_48_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_32230601_49_dialog_content = "... Chen'ni?",
  ui_story_32230601_50_dialog_content = "Ha! Que petisco interessante!",
  ui_story_32230601_51_dialog_content = "Fico feliz que tenha gostado, eu acho... Aqui, pegue a minha mão antes que fique tonto de nadar depois de comer.",
  ui_story_32230601_52_dialog_content = "Ah, minhas roupas estão todas encharcadas.",
  ui_story_32230601_53_dialog_content = "Huh? Mas você acabou de dizer que suas roupas eram impenetráveis para—",
  ui_story_32230601_54_dialog_content = "Oh querido, o que vou fazer agora? Isso é uma grande dúvida.",
  ui_story_32230601_55_dialog_content = "Apenas use seus poderes—",
  ui_story_32230601_56_dialog_content = "Eu me pergunto onde eu poderia encontrar um conjunto de roupas novas?",
  ui_story_32230601_57_dialog_content = "*olha*",
  ui_story_32230601_58_dialog_content = "Bem, se você vai ficar me encarando assim... Aqui está.",
  ui_story_32230601_59_dialog_content = "Às vezes, acho que você pode ser melhor em ler mentes do que um Celestita, Chen'ni.",
  ui_story_32230601_60_dialog_content = "Eu não tenho ideia do que está falando!",
  ui_story_32230601_61_dialog_content = "Até mesmo um dragão como eu esquece como manter sua magia de vez em quando.",
  ui_story_32230601_62_dialog_content = "Claro, o que você disser. Só venha aqui em cima, pode?",
  ui_story_32230601_63_dialog_content = "Acontece que eu tenho um vestido só para você.",
  ui_story_32230601_64_dialog_content = "Oh, PlayerName!",
  ui_story_32230601_65_dialog_content = "Esse vestido é tão fofo! Eu amo ele!",
  ui_story_32230601_66_dialog_content = "Eu tenho querido experimentar as roupas do Astra por tanto tempo agora!",
  ui_story_32230601_67_dialog_content = "Que bom que gostou.",
  ui_story_32230601_68_dialog_content = "Eu queria perguntar, mas o que você está fazendo aqui, afinal?",
  ui_story_32230601_69_dialog_content = "Ah, bem...",
  ui_story_32230601_70_dialog_content = "Na verdade, estou procurando por um desejo.",
  ui_story_32230601_71_dialog_content = "Um desejo?",
  ui_story_32230601_72_dialog_content = "Sempre que alguém reza para mim e me envia uma oferta, eu posso ouvir os desejos mais profundos do seu coração!",
  ui_story_32230601_73_dialog_content = "Afinal, viver no reino mortal é ter desejos.",
  ui_story_32230601_74_dialog_content = "Alguns anseiam por riqueza, autoridade, amor ou um lugar para chamar de seu. Outros apenas desejam que as coisas aconteçam do seu jeito.",
  ui_story_32230601_75_dialog_content = "Mas este desejo é diferente do habitual.",
  ui_story_32230601_76_dialog_content = "Tudo o que sei é que alguém fez uma oferta para mim, mas por algum motivo, eu não consegui ouvir claramente o seu desejo.",
  ui_story_32230601_77_dialog_content = "Eu não tive escolha a não ser aparecer e descobrir por que esse desejo era tão difícil de entender!",
  ui_story_32230601_78_dialog_content = "Entendi, então você veio ao festival procurando por alguém.",
  ui_story_32230601_79_dialog_content = "Deixe-me ajudá-lo então. Talvez minha habilidade psíquica possa ser útil aqui.",
  ui_story_32230601_80_dialog_content = "PlayerName...",
  ui_story_32230601_81_dialog_content = "O que foi?",
  ui_story_32230601_82_dialog_content = "Nada. Por que você não tenta usar seus poderes em mim?",
  ui_story_32230601_83_dialog_content = "Assim, posso compartilhar o que ouço com você.",
  ui_story_32230601_84_option_content = "Aumento de Força",
  ui_story_32230601_85_dialog_content = "Donzela do Dragão, ouça meu pedido, desejo ser promovido este ano e fazer fortuna.",
  ui_story_32230601_86_dialog_content = "Todo-Poderoso Dragão Divino Benevolente! Por favor, mantenha-me seguro nesta viagem!",
  ui_story_32230601_87_dialog_content = "Ó poderosa Donzela Dragão, será que algum dia encontrarei o cara dos meus sonhos?",
  ui_story_32230601_88_dialog_content = "Ugh...",
  ui_story_32230601_89_dialog_content = "Você está bem?",
  ui_story_32230601_90_dialog_content = "Sim, só um pouco tonto por causa de todas aquelas vozes na sua mente agora mesmo.",
  ui_story_32230601_91_dialog_content = "É isso que você tem que ouvir a cada segundo de todos os dias?",
  ui_story_32230601_92_dialog_content = "Isso mesmo. Eu sou uma deusa, lembra?",
  ui_story_32230601_93_dialog_content = "Uau, eu continuo perdendo nas batalhas na grama. Você pode me ajudar, Donzela do Dragão?",
  ui_story_32230601_94_dialog_content = "P-Pessoas realmente desejam coisas assim? Huh? Para onde Chen'ni foi?",
  ui_story_32230601_95_dialog_content = "Este jogo parece muito divertido! Como se joga?",
  ui_story_32230601_96_dialog_content = "É chamado de batalha na grama, minha querida.",
  ui_story_32230601_97_dialog_content = "Primeiro, temos que encontrar dois talos de grama longos. Depois cruzamos eles e puxamos, e quem quebrar o talo do outro vence.",
  ui_story_32230601_98_dialog_content = "Se você ganhar três vezes seguidas, ganha este lindo grampo de cabelo.",
  ui_story_32230601_99_dialog_content = "(Minha mamãe está muito doente para sair de casa. Quero animá-la ganhando isso para ela, mas eu só continuo perdendo...)",
  ui_story_32230601_100_dialog_content = "Quero brincar!",
  ui_story_32230601_101_dialog_content = "Agora mesmo? Claro, mas onde vamos encontrar grama para o jogo?",
  ui_story_32230601_102_dialog_content = "<color=#e8d9bb>Sem hesitar por um momento, Chen'ni arranca um único pelo de sua cauda.</color>",
  ui_story_32230601_103_dialog_content = "Aqui, use isso!",
  ui_story_32230601_104_dialog_content = "Ei!",
  ui_story_32230601_105_dialog_content = "(Mas isso seria trapaça!)",
  ui_story_32230601_106_dialog_content = "(Não se preocupe, usarei meus poderes para garantir que ninguém perceba.)",
  ui_story_32230601_107_dialog_content = "(Oh, então agora você pode usar sua magia?)",
  ui_story_32230601_108_dialog_content = "<color=#e8d9bb>Três partidas depois</color>",
  ui_story_32230601_109_dialog_content = "Eu ganhei!",
  ui_story_32230601_110_dialog_content = "Mal posso acreditar! Estive jogando o dia todo, mas você é a primeira pessoa a me derrotar.",
  ui_story_32230601_111_dialog_content = "Aqui, este grampo de cabelo é seu agora.",
  ui_story_32230601_112_dialog_content = "Olha, PlayerName! Eu ganhei!",
  ui_story_32230601_113_dialog_content = "Uau, isso é incrível.",
  ui_story_32230601_114_dialog_content = "(Mesmo que você tenha trapaceado totalmente...)",
  ui_story_32230601_115_dialog_content = "Batalhas na grama são muito divertidas, mas eu realmente não preciso deste grampo de cabelo.",
  ui_story_32230601_116_dialog_content = "Acho que vou ter que me livrar disso!",
  ui_story_32230601_117_dialog_content = "<color=#e8d9bb>Chen'ni joga o grampo de cabelo no ar, onde ele gira duas vezes antes de pousar suavemente nas mãos da garotinha.</color>",
  ui_story_32230601_118_dialog_content = "É a Donzela Dragão! Ela realmente está aqui!",
  ui_story_32230601_119_dialog_content = "Pare de ficar parado, PlayerName! Ainda há muitas coisas divertidas para fazer!",
  ui_story_32230601_120_dialog_content = "Tô indo aí—huh?",
  ui_story_32230601_121_dialog_content = "Tão doce... Muita fome.",
  ui_story_32230601_122_dialog_content = "Essa voz... Isso também conta como um desejo?",
  ui_story_32230601_123_dialog_content = "Aproxime-se do maior concurso de embrulho de zongzi do Festival das Cores! Inscreva-se com um amigo antes do início da próxima rodada!",
  ui_story_32230601_124_dialog_content = "PlayerName!",
  ui_story_32230601_125_dialog_content = "Deixe-me adivinhar - você quer se inscrever, não quer?",
  ui_story_32230601_126_dialog_content = "Aham!",
  ui_story_32230601_127_dialog_content = "As regras são simples: a equipe que embrulhar mais zongzi antes que este bastão de incenso se apague ganha um prêmio fabuloso!",
  ui_story_32230601_128_dialog_content = "E comece!",
  ui_story_32230601_129_dialog_content = "Eu sei que é um pouco estranho da minha parte dizer isso agora.",
  ui_story_32230601_130_dialog_content = "Mas Chen'ni...",
  ui_story_32230601_131_dialog_content = "Você sabe mesmo como embrulhar esse tal de \"zongzi\"?",
  ui_story_32230601_132_dialog_content = "Não mesmo.",
  ui_story_32230601_133_dialog_content = "Nem eu.",
  ui_story_32230601_134_dialog_content = "M-Mesmo...? Devemos ver como outras pessoas fazem primeiro?",
  ui_story_32230601_135_dialog_content = "...",
  ui_story_32230601_136_dialog_content = "É surpreendentemente simples de fazer. Acho que conseguimos!",
  ui_story_32230601_137_dialog_content = "A competição está agora pela metade! Vamos continuar torcendo por nossas equipes!",
  ui_story_32230601_138_dialog_content = "Está ficando cada vez mais fácil embrulhar esses. Acho que temos uma chance real de ganhar agora! Quantos nós temos—",
  ui_story_32230601_139_dialog_content = "Uh, onde estão todos os zongzi que acabei de embrulhar?",
  ui_story_32230601_140_dialog_content = "Arroto!",
  ui_story_32230601_141_dialog_content = "... Não! Cuspa isso agora mesmo! Ainda está cru!",
  ui_story_32230601_142_dialog_content = "<color=#e8d9bb>Momentos depois</color>",
  ui_story_32230601_143_dialog_content = "Acabou o tempo! A competição acabou agora!",
  ui_story_32230601_144_dialog_content = "Que rápido!",
  ui_story_32230601_145_dialog_content = "No final, só tivemos tempo suficiente para embrulhar um único zongzi.",
  ui_story_32230601_146_dialog_content = "Não ganhamos nada, mas o dono da barraca foi gentil o suficiente para cozinhar para nós. Também cheira muito gostoso.",
  ui_story_32230601_147_dialog_content = "Rangido...",
  ui_story_32230601_148_dialog_content = "Hã? Foi a sua voz que eu ouvi mais cedo?",
  ui_story_32230601_149_dialog_content = "Aqui, pegue este zongzi. O recheio é de tâmaras vermelhas, então é bem doce e agradável.",
  ui_story_32230601_150_dialog_content = "Rangido!",
  ui_story_32230601_151_dialog_content = "<color=#e8d9bb>O pequeno demônio pula e beija PlayerName na mão antes de sair correndo feliz com seu zongzi.</color>",
  ui_story_32230601_152_dialog_content = "Aquela coisinha realmente gosta de você, PlayerName.",
  ui_story_32230601_153_dialog_content = "... É engraçado.",
  ui_story_32230601_154_dialog_content = "Mesmo que não tenhamos ganhado nada, ainda me sinto muito feliz.",
  ui_story_32230601_155_dialog_content = "Isso é o tipo de coisa que você costuma fazer? Ouvir os corações dos outros e conceder seus desejos?",
  ui_story_32230601_156_dialog_content = "Para uma deusa como você, não podemos ser muito mais do que visitantes passageiros em sua vida.",
  ui_story_32230601_157_dialog_content = "O que isso tem a ver com alguma coisa? Você está feliz agora, não está?",
  ui_story_32230601_158_dialog_content = "Eu também!",
  ui_story_32230601_159_dialog_content = "Em meus olhos, suas vidas são inegavelmente curtas.",
  ui_story_32230601_160_dialog_content = "Mas é possível que minha vida seja tão passageira no grande esquema da existência.",
  ui_story_32230601_161_dialog_content = "Nesse sentido, somos todos iguais - aurorianos, fiendlings e nós dois também.",
  ui_story_32230601_162_dialog_content = "Estamos limitados em nossa existência, sim.",
  ui_story_32230601_163_dialog_content = "Mas bem aqui e agora, estamos aproveitando os mesmos momentos passageiros juntos, não estamos?",
  ui_story_32230601_164_dialog_content = "É natural querer tornar esses momentos o mais alegres possível.",
  ui_story_32230601_165_dialog_content = "Então vamos lá! Tenho a sensação de que ainda temos muitos momentos felizes para aproveitar!",
  ui_story_32230601_166_dialog_content = "Claro!",
  ui_story_32230601_167_dialog_content = "Bem, o que você disse pode ser verdade...",
  ui_story_32230601_168_dialog_content = "Mas Chen'ni... Você acha que talvez possamos fazer uma pausa primeiro?",
  ui_story_32230601_169_dialog_content = "Já está cansado, PlayerName?",
  ui_story_32230601_170_dialog_content = "Bem, sim! Nós tivemos batalhas na grama, enrolamos zongzi, colhemos ervas e ajudamos um ferreiro em sua forja...",
  ui_story_32230601_171_dialog_content = "Até participamos de três corridas de barco dragão como substitutos de última hora!",
  ui_story_32230601_172_dialog_content = "Seria estranho se eu não estivesse cansado!",
  ui_story_32230601_173_dialog_content = "Tudo bem então, aqui está um pedaço de bolo de arroz para ajudá-lo a recuperar suas forças.",
  ui_story_32230601_174_dialog_content = "Obrigado... Mas onde você conseguiu isso?",
  ui_story_32230601_175_dialog_content = "De uma oferta!",
  ui_story_32230601_176_dialog_content = "Vê? Há um santuário dedicado a mim logo à frente.",
  ui_story_32230601_177_dialog_content = "Até aqui, hein? Todos devem realmente respeitar você, Chen'ni.",
  ui_story_32230601_178_dialog_content = "Quê? Isso é...",
  ui_story_32230601_179_dialog_content = "Muito obrigado, Donzela do Dragão. Minha mãe amou muito o presente dela.",
  ui_story_32230601_180_dialog_content = "Elogio você, minha deusa, meu negócio foi especialmente bem hoje.",
  ui_story_32230601_181_dialog_content = "Rangido!",
  ui_story_32230601_182_dialog_content = "<color=#e8d9bb>Um a um, as pessoas deixam todos os tipos de oferendas no santuário. Até aquele pequeno demônio deixa uma flor silvestre ao lado do santuário.</color>",
  ui_story_32230601_183_dialog_content = "Por que todos eles também deixaram esse tópico para trás?",
  ui_story_32230601_184_dialog_content = "Durante o Festival das Cores, é costume as pessoas enviarem umas às outras fios coloridos como presentes.",
  ui_story_32230601_185_dialog_content = "Cada uma das cinco cores representa um significado ou desejo diferente.",
  ui_story_32230601_186_dialog_content = "Ao trançar as cinco cores em uma pulseira e usá-la, as pessoas podem melhorar sua sorte e evitar desastres.",
  ui_story_32230601_187_dialog_content = "Oferecer esses fios para mim também é a maneira deles de expressar gratidão.",
  ui_story_32230601_188_dialog_content = "Infelizmente, só vejo quatro cores aqui, não cinco.",
  ui_story_32230601_189_dialog_content = "Mas nada é sempre perfeito, certo?",
  ui_story_32230601_190_dialog_content = "Assim como nos divertimos muito hoje, apesar de não encontrar a pessoa que fez aquele estranho pedido.",
  ui_story_32230601_191_dialog_content = "Não, eu definitivamente o encontrei há muito tempo.",
  ui_story_32230601_192_dialog_content = "Sério? Quando isso aconteceu?",
  ui_story_32230601_193_dialog_content = "Logo quando eu peguei este vestido, na verdade.",
  ui_story_32230601_194_dialog_content = "Essa voz era sua, PlayerName.",
  ui_story_32230601_195_dialog_content = "?",
  ui_story_32230601_196_dialog_content = "Sua oferta me agradou muito. Fale seu desejo, e eu o concederei para você.",
  ui_story_32230601_197_option_content = "Bem, eu tenho um desejo.",
  ui_story_32230601_198_dialog_content = "Então, nomeie sua ambição ou o objeto que deseja, e eu farei com que seja seu.",
  ui_story_32230601_199_dialog_content = "Não estou interessado em nada disso.",
  ui_story_32230601_200_option_content = "Eu não tenho um desejo.",
  ui_story_32230601_201_dialog_content = "Por quê?",
  ui_story_32230601_202_dialog_content = "Porque aquele vestido não era uma oferta, nem minha maneira de pedir um desejo.",
  ui_story_32230601_203_dialog_content = "Eu só queria te dar um presente, Chen'ni.",
  ui_story_32230601_204_dialog_content = "Se eu tivesse que atribuir um desejo a isso...",
  ui_story_32230601_205_dialog_content = "Então, definitivamente seria para o seu bem.",
  ui_story_32230601_206_dialog_content = "Dragão Divino Todo-Poderoso e Benevolente, ouça meu apelo—",
  ui_story_32230601_207_dialog_content = "Meu desejo é que você seja sempre tão feliz!",
  ui_story_32230601_208_dialog_content = "Depois de todos esses anos, perdi a conta de quantas pessoas fizeram desejos para eu conceder. Por que você faria um desejo por minha causa?",
  ui_story_32230601_209_dialog_content = "Mesmo que você faça um desejo bastante egoísta, eu não me importaria em concedê-lo.",
  ui_story_32230601_210_dialog_content = "Tem certeza de que não vai se arrepender de desperdiçar uma oportunidade tão rara?",
  ui_story_32230601_211_dialog_content = "Claro que não vou.",
  ui_story_32230601_212_dialog_content = "Presentes são feitos para fazer as pessoas felizes, e é só isso.",
  ui_story_32230601_213_dialog_content = "Já que você chama isso de presente...",
  ui_story_32230601_214_dialog_content = "É apropriado que eu te dê algo em troca.",
  ui_story_32230601_215_dialog_content = "Ah, não se preocupe com isso. Eu apenas aconteci de comprar por impulso—",
  ui_story_32230601_216_dialog_content = "Estenda sua mão, PlayerName.",
  ui_story_32230601_217_dialog_content = "<color=#e8d9bb>De repente, o vento ao redor deles para completamente.</color>",
  ui_story_32230601_218_dialog_content = "<color=#e8d9bb>Com um gesto, Chen'ni convoca um fio verde de seu santuário, que flutua e circunda o pulso de PlayerName.</color>",
  ui_story_32230601_219_dialog_content = "Um fio de verde para representar a floresta, o leste e a primavera que dá vida.",
  ui_story_32230601_220_dialog_content = "May os ventos da primavera trazem a você saúde e felicidade.",
  ui_story_32230601_221_dialog_content = "<color=#e8d9bb>Um fio vermelho flutua e se entrelaça ao redor do fio verde.</color>",
  ui_story_32230601_222_dialog_content = "Um fio de vermelho para representar o fogo, o sul e o florescente verão.",
  ui_story_32230601_223_dialog_content = "May o calor do verão traga-lhe força e valor.",
  ui_story_32230601_224_dialog_content = "<color=#e8d9bb>Um fio branco desliza e se entrelaça com os outros dois.</color>",
  ui_story_32230601_225_dialog_content = "Um fio de branco para representar o trovão, o oeste e o outono abundante.",
  ui_story_32230601_226_dialog_content = "May a colheita de outono traga sucesso em todos os seus empreendimentos.",
  ui_story_32230601_227_dialog_content = "<color=#e8d9bb>Um fio preto flutua e habilmente se adiciona à pulseira.</color>",
  ui_story_32230601_228_dialog_content = "Um fio de preto para representar a água, o norte e o inevitável inverno.",
  ui_story_32230601_229_dialog_content = "May as tempestades de inverno tragam a você nova vida e iluminação.",
  ui_story_32230601_230_dialog_content = "<color=#e8d9bb>Com isso, todos os fios no santuário foram usados.</color>",
  ui_story_32230601_231_dialog_content = "Mesmo com apenas quatro cores, esta pulseira é absolutamente linda. Eu amo isso!",
  ui_story_32230601_232_dialog_content = "Isso é ótimo e tudo mais, mas que tipo de amigo eu seria se te desse um presente inacabado? Olha só!",
  ui_story_32230601_233_dialog_content = "<color=#e8d9bb>Chen'ni levanta a mão e junta os dedos. Sua energia divina surge e forma um fio dourado no ar.</color>",
  ui_story_32230601_234_dialog_content = "Um fio de ouro para representar o centro, o dragão, e...",
  ui_story_32230601_235_dialog_content = "Eu!",
  ui_story_32230601_236_dialog_content = "Hã?",
  ui_story_32230601_237_dialog_content = "<color=#e8d9bb>Se você levantar o rosto agora, verá os olhos dela brilhando de alegria.</color>",
  ui_story_32230601_238_dialog_content = "Vou dizer isso apenas uma vez, PlayerName—",
  ui_story_32230601_239_dialog_content = "Por favor, mantenha-se saudável e viva uma vida mais longa.",
  ui_story_32230601_240_dialog_content = "Dessa forma, podemos compartilhar ainda mais momentos felizes juntos.",
  ui_story_32230601_241_dialog_content = "Mesmo que provavelmente não seja nada comparado à sua expectativa de vida...",
  ui_story_32230601_242_dialog_content = "Farei o meu melhor para continuar.",
  ui_story_32230601_243_dialog_content = "Isso não deve ser muito difícil, já que tenho você cuidando de mim.",
  ui_story_32230601_244_dialog_content = "<color=#e8d9bb>Chen'ni cuidadosamente amarra as duas pontas da pulseira juntas, o fio dourado brilha intensamente entre as outras quatro cores.</color>",
  ui_story_32230601_245_dialog_content = "May toda a beleza do mundo dance em seu nome, e May sua sábia liderança floresça por mil anos.",
  ui_story_32230601_246_dialog_content = "May todas as coisas neste mundo se prestam à realização de seus desejos...",
  ui_story_32230601_247_dialog_content = "Por toda a eternidade."
}
return config
